insert into lifestyle.exercises (slug, name, category, muscle_groups, equipment, joints, difficulty, variant_of, technique)
values
  ('liegestuetz', 'Liegestütz', 'bodyweight', '{brust,trizeps,schulter}', '{}', '{schulter,handgelenk}', 2, null, 'Hände unter den Schultern aufsetzen und den Körper in einer Linie halten. Brust kontrolliert absenken und wieder hochdrücken. Der Blick geht leicht nach vorn zum Boden.'),
  ('liegestuetz-knie', 'Liegestütz auf Knien', 'bodyweight', '{brust,trizeps,schulter}', '{}', '{schulter,handgelenk}', 1, 'liegestuetz', 'Knie am Boden ablegen, Hände unter den Schultern. Oberkörper und Oberschenkel bilden eine Linie. Brust kontrolliert absenken und wieder hochdrücken.'),
  ('kniebeuge-koerpergewicht', 'Kniebeuge (Körpergewicht)', 'bodyweight', '{beine,gesaess}', '{}', '{knie,huefte}', 1, null, 'Füße schulterbreit aufstellen. Gesäß nach hinten unten schieben, die Knie zeigen in Richtung der Zehen. Oberkörper aufrecht halten und wieder aufstehen.'),
  ('ausfallschritt', 'Ausfallschritt', 'bodyweight', '{beine,gesaess}', '{}', '{knie,huefte}', 2, null, 'Einen großen Schritt nach vorn machen und beide Knie beugen. Das hintere Knie geht in Richtung Boden, der Oberkörper bleibt aufrecht. Über das vordere Bein zurück in den Stand drücken.'),
  ('glute-bridge', 'Beckenheben', 'bodyweight', '{gesaess,beine}', '{}', '{huefte}', 1, null, 'Auf den Rücken legen und die Füße hüftbreit aufstellen. Becken anheben, bis Oberkörper und Oberschenkel eine Linie bilden. Kurz halten und kontrolliert absenken.'),
  ('plank', 'Unterarmstütz (Plank)', 'bodyweight', '{rumpf}', '{}', '{schulter,ruecken}', 1, null, 'Ellbogen unter den Schultern aufsetzen. Der Körper bildet eine Linie, Bauch und Gesäß sind angespannt. Ruhig weiteratmen.'),
  ('seitstuetz', 'Seitstütz', 'bodyweight', '{rumpf,schulter}', '{}', '{schulter}', 2, null, 'Seitlich auf den Unterarm stützen, der Ellbogen steht unter der Schulter. Hüfte anheben, bis der Körper eine Linie bildet. Position halten und ruhig atmen, dann die Seite wechseln.'),
  ('crunch', 'Crunch', 'bodyweight', '{rumpf}', '{}', '{ruecken}', 1, null, 'Auf den Rücken legen und die Füße aufstellen. Schulterblätter langsam vom Boden lösen, der untere Rücken bleibt liegen. Kontrolliert wieder ablegen.'),
  ('superman', 'Rückenstrecker am Boden', 'bodyweight', '{ruecken,gesaess}', '{}', '{ruecken}', 1, null, 'Auf den Bauch legen und die Arme nach vorn strecken. Arme und Beine wenige Zentimeter anheben, der Blick bleibt zum Boden. Kurz halten und wieder ablegen.'),
  ('dips-stuhl', 'Dips am Stuhl', 'bodyweight', '{trizeps,brust,schulter}', '{}', '{schulter,handgelenk}', 2, null, 'Hände hinter dem Körper auf eine stabile Stuhlkante stützen. Ellbogen nach hinten beugen und den Körper absenken. Aus den Armen wieder hochdrücken.'),
  ('wandsitz', 'Wandsitz', 'bodyweight', '{beine}', '{}', '{knie}', 1, null, 'Mit dem Rücken an eine Wand lehnen und in eine sitzende Position rutschen. Die Knie stehen über den Fersen. Position halten und gleichmäßig atmen.'),
  ('bergsteiger', 'Bergsteiger', 'bodyweight', '{rumpf,schulter,beine}', '{}', '{schulter,handgelenk}', 2, null, 'In den hohen Stütz gehen, die Hände stehen unter den Schultern. Die Knie abwechselnd zügig in Richtung Brust ziehen. Die Hüfte bleibt dabei ruhig.'),
  ('umgekehrtes-rudern-tisch', 'Rudern unter dem Tisch', 'bodyweight', '{ruecken,bizeps}', '{}', '{schulter}', 2, null, 'Unter einen stabilen Tisch legen und die Tischkante greifen. Den Körper gestreckt halten und die Brust zur Kante ziehen. Kontrolliert wieder ablassen.'),
  ('bankdruecken-kurzhantel', 'Bankdrücken mit Kurzhanteln', 'kraft', '{brust,trizeps,schulter}', '{kurzhanteln}', '{schulter,handgelenk}', 2, null, 'Auf den Rücken legen und die Schulterblätter zusammenziehen. Hanteln kontrolliert zur Brust senken. Über der Brust wieder nach oben drücken.'),
  ('rudern-kurzhantel', 'Rudern mit Kurzhantel', 'kraft', '{ruecken,bizeps}', '{kurzhanteln}', '{ruecken,schulter}', 1, null, 'Eine Hand und ein Knie abstützen, der Rücken bleibt gerade. Hantel zur Hüfte ziehen. Kontrolliert wieder absenken.'),
  ('schulterdruecken-kurzhantel', 'Schulterdrücken mit Kurzhanteln', 'kraft', '{schulter,trizeps}', '{kurzhanteln}', '{schulter}', 2, null, 'Hanteln auf Schulterhöhe halten, die Handflächen zeigen nach vorn. Hanteln nach oben drücken, ohne ins Hohlkreuz zu gehen. Kontrolliert zurück auf Schulterhöhe senken.'),
  ('seitheben-kurzhantel', 'Seitheben mit Kurzhanteln', 'kraft', '{schulter}', '{kurzhanteln}', '{schulter}', 1, null, 'Aufrecht stehen, die Hanteln hängen neben dem Körper. Arme leicht gebeugt seitlich bis auf Schulterhöhe heben. Langsam wieder absenken.'),
  ('bizepscurl-kurzhantel', 'Bizepscurl mit Kurzhanteln', 'kraft', '{bizeps}', '{kurzhanteln}', '{handgelenk}', 1, null, 'Aufrecht stehen, die Ellbogen bleiben am Körper. Hanteln zur Schulter beugen. Langsam wieder strecken, ohne Schwung zu holen.'),
  ('trizepsdruecken-kurzhantel', 'Trizepsdrücken über Kopf', 'kraft', '{trizeps}', '{kurzhanteln}', '{schulter}', 2, null, 'Eine Hantel mit beiden Händen über den Kopf halten. Ellbogen beugen und die Hantel hinter den Kopf senken. Arme wieder strecken, die Ellbogen zeigen nach vorn.'),
  ('goblet-kniebeuge', 'Kniebeuge mit Kurzhantel (Goblet)', 'kraft', '{beine,gesaess,rumpf}', '{kurzhanteln}', '{knie,huefte}', 2, null, 'Eine Hantel mit beiden Händen vor der Brust halten. Gesäß nach hinten unten schieben, der Oberkörper bleibt aufrecht. Aus den Beinen wieder aufrichten.'),
  ('ausfallschritt-kurzhantel', 'Ausfallschritt mit Kurzhanteln', 'kraft', '{beine,gesaess}', '{kurzhanteln}', '{knie,huefte}', 3, 'ausfallschritt', 'Hanteln neben dem Körper halten und einen großen Schritt nach vorn machen. Beide Knie beugen, der Oberkörper bleibt aufrecht. Über das vordere Bein zurück in den Stand drücken.'),
  ('kreuzheben-kurzhantel', 'Rumänisches Kreuzheben mit Kurzhanteln', 'kraft', '{beine,gesaess,ruecken}', '{kurzhanteln}', '{ruecken,huefte}', 2, null, 'Hanteln vor den Oberschenkeln halten, die Knie sind leicht gebeugt. Hüfte nach hinten schieben und die Hanteln mit geradem Rücken entlang der Beine senken. Über die Hüfte wieder aufrichten.'),
  ('fliegende-kurzhantel', 'Fliegende mit Kurzhanteln', 'kraft', '{brust,schulter}', '{kurzhanteln}', '{schulter}', 2, null, 'Auf den Rücken legen und die Hanteln über der Brust halten. Arme leicht gebeugt in einem Bogen zur Seite senken. Auf demselben Weg wieder zusammenführen.'),
  ('kniebeuge-langhantel', 'Kniebeuge mit Langhantel', 'kraft', '{beine,gesaess,rumpf}', '{langhantel}', '{knie,huefte,ruecken}', 3, null, 'Stange fest auf dem oberen Rücken ablegen und den Rumpf anspannen. Kontrolliert absenken, die Knie zeigen in Richtung der Zehen. Aus den Beinen wieder aufrichten.'),
  ('kreuzheben-langhantel', 'Kreuzheben mit Langhantel', 'kraft', '{ruecken,beine,gesaess}', '{langhantel}', '{ruecken,huefte}', 3, null, 'Hüftbreit an die Stange stellen und sie mit geradem Rücken greifen. Stange nah am Körper nach oben führen, bis Hüfte und Knie gestreckt sind. Kontrolliert wieder absetzen.'),
  ('bankdruecken-langhantel', 'Bankdrücken mit Langhantel', 'kraft', '{brust,trizeps,schulter}', '{langhantel}', '{schulter,handgelenk}', 3, null, 'Auf den Rücken legen, die Schulterblätter zusammenziehen und die Stange etwas weiter als schulterbreit greifen. Stange kontrolliert zur Brust senken. Wieder nach oben drücken.'),
  ('latzug-kabel', 'Latzug am Kabelzug', 'kraft', '{ruecken,bizeps}', '{kabelzug}', '{schulter}', 1, null, 'Aufrecht sitzen und die Stange etwas weiter als schulterbreit greifen. Stange zur oberen Brust ziehen, die Ellbogen gehen nach unten. Langsam wieder nach oben führen.'),
  ('trizepsdruecken-kabel', 'Trizepsdrücken am Kabelzug', 'kraft', '{trizeps}', '{kabelzug}', '{handgelenk}', 1, null, 'Aufrecht vor dem Kabelzug stehen, die Ellbogen bleiben am Körper. Griff nach unten drücken, bis die Arme gestreckt sind. Langsam wieder nach oben führen.'),
  ('rudern-band', 'Rudern mit Band', 'kraft', '{ruecken,bizeps}', '{baender}', '{schulter}', 1, null, 'Band auf Brusthöhe befestigen und beide Enden greifen. Ellbogen eng am Körper nach hinten ziehen und die Schulterblätter zusammenführen. Langsam wieder nach vorn führen.'),
  ('beinpresse', 'Beinpresse', 'kraft', '{beine,gesaess}', '{studio}', '{knie,huefte}', 1, null, 'Füße schulterbreit auf die Platte stellen, der Rücken liegt an. Platte wegdrücken, ohne die Knie ganz durchzustrecken. Kontrolliert wieder zurückkommen.'),
  ('joggen', 'Joggen', 'cardio', '{beine}', '{}', '{knie,huefte}', 1, null, 'Aufrechte Haltung und lockere Schultern. Gleichmäßiger Schritt in einem Tempo, bei dem Sprechen noch möglich ist.'),
  ('zuegiges-gehen', 'Zügiges Gehen', 'cardio', '{beine}', '{}', '{}', 1, null, 'Aufrecht gehen und die Arme locker mitschwingen. Ein Tempo wählen, das sich zügig anfühlt, bei dem Sprechen aber noch möglich ist.'),
  ('seilspringen', 'Seilspringen', 'cardio', '{beine}', '{}', '{knie}', 2, null, 'Aufrecht stehen und locker auf den Fußballen springen. Die Sprünge bleiben klein, die Knie federn leicht nach. Geht auch ohne Seil mit kreisenden Handgelenken.'),
  ('hampelmann', 'Hampelmann', 'cardio', '{beine,schulter}', '{}', '{knie,schulter}', 1, null, 'Aus dem Stand in eine Grätsche springen und die Arme über den Kopf führen. Zurück in den Stand springen und die Arme senken. Gleichmäßig weitermachen.'),
  ('radfahren-ergometer', 'Radfahren auf dem Ergometer', 'cardio', '{beine}', '{kardio}', '{knie}', 1, null, 'Sattel so einstellen, dass das Knie unten leicht gebeugt bleibt. Gleichmäßig treten in einem Tempo, bei dem Sprechen noch möglich ist.'),
  ('rudergeraet', 'Rudern am Rudergerät', 'cardio', '{ruecken,beine}', '{kardio}', '{ruecken,knie}', 2, null, 'Zuerst mit den Beinen abdrücken, dann den Oberkörper leicht nach hinten nehmen und den Griff zum Bauch ziehen. In umgekehrter Reihenfolge zurück nach vorn gleiten. Der Rücken bleibt gerade.'),
  ('crosstrainer', 'Crosstrainer', 'cardio', '{beine}', '{kardio}', '{}', 1, null, 'Aufrecht stehen und die Griffe locker fassen. Gleichmäßig bewegen in einem Tempo, bei dem Sprechen noch möglich ist.'),
  ('huefte-kreisen', 'Hüftkreisen', 'mobility', '{huefte}', '{}', '{huefte}', 1, null, 'Aufrecht stehen und die Hände an die Hüfte legen. Große, langsame Kreise in beide Richtungen ausführen.'),
  ('katze-kuh', 'Katze-Kuh', 'mobility', '{ruecken,rumpf}', '{}', '{ruecken,handgelenk}', 1, null, 'In den Vierfüßlerstand gehen. Den Rücken langsam rund machen und danach sanft ins leichte Hohlkreuz gehen. Im eigenen Atemrhythmus wechseln.'),
  ('schulterkreisen', 'Schulterkreisen', 'mobility', '{schulter}', '{}', '{schulter}', 1, null, 'Aufrecht stehen und die Arme locker hängen lassen. Schultern in großen, langsamen Kreisen nach hinten und danach nach vorn bewegen.'),
  ('brustwirbel-rotation', 'Rotation der Brustwirbelsäule', 'mobility', '{ruecken}', '{}', '{ruecken}', 1, null, 'In den Vierfüßlerstand gehen und eine Hand an den Hinterkopf legen. Den Ellbogen langsam zur Decke drehen und wieder zurück. Danach die Seite wechseln.'),
  ('oberschenkel-dehnen', 'Oberschenkel dehnen', 'dehnen', '{beine}', '{}', '{knie}', 1, null, 'Im Stand die Ferse zum Gesäß führen, die Knie bleiben nebeneinander. Position ruhig halten und gleichmäßig atmen.'),
  ('hueftbeuger-dehnen', 'Hüftbeuger dehnen', 'dehnen', '{huefte,beine}', '{}', '{huefte,knie}', 1, null, 'In einen tiefen Ausfallschritt gehen und das hintere Knie ablegen. Die Hüfte sanft nach vorn schieben, der Oberkörper bleibt aufrecht. Position ruhig halten, dann die Seite wechseln.'),
  ('brust-dehnen', 'Brust dehnen an der Wand', 'dehnen', '{brust,schulter}', '{}', '{schulter}', 1, null, 'Seitlich an eine Wand stellen und den Unterarm auf Schulterhöhe anlegen. Den Oberkörper langsam von der Wand wegdrehen. Position ruhig halten, dann die Seite wechseln.'),
  ('waden-dehnen', 'Waden dehnen', 'dehnen', '{beine}', '{}', '{}', 1, null, 'Mit den Händen an einer Wand abstützen und ein Bein nach hinten stellen. Die hintere Ferse bleibt am Boden, das Knie ist gestreckt. Position ruhig halten, dann die Seite wechseln.')
